    "textDispositions": [
      {
        "character": 2,
        "role": "offstage-duplicate-title",
        "sourceText": "Multiplication:  Important Words"
      },
      {
        "character": 4,
        "role": "native-text",
        "sourceText": "Multiplication: Important Words"
      },
      {
        "character": 8,
        "role": "native-text",
        "sourceText": "Multiply means to find the total of a number of equal groups."
      },
      {
        "character": 16,
        "role": "native-text",
        "sourceText": "6 × 4 = 24 "
      },
      {
        "character": 17,
        "role": "native-text",
        "sourceText": "5"
      },
      {
        "character": 18,
        "role": "native-calculation-separator",
        "sourceText": "___"
      },
      {
        "character": 19,
        "role": "native-text",
        "sourceText": "185"
      },
      {
        "character": 20,
        "role": "native-text",
        "sourceText": "37"
      },
      {
        "character": 21,
        "role": "native-text",
        "sourceText": "×"
      },
      {
        "character": 22,
        "role": "native-text",
        "sourceText": "3 groups of 5 ="
      },
      {
        "character": 23,
        "role": "native-text",
        "sourceText": "= 15"
      },
      {
        "character": 28,
        "role": "native-text",
        "sourceText": "Multiply means repeated addition."
      },
      {
        "character": 33,
        "role": "native-text",
        "sourceText": "6 + 6 + 6 + 6 = 24"
      },
      {
        "character": 34,
        "role": "native-text",
        "sourceText": "37 + 37 + 37 + 37 + 37 = 185"
      },
      {
        "character": 35,
        "role": "native-text",
        "sourceText": "5 + 5 + 5 = 15"
      }
    ],
